import "./App.css";

function App() {
  return (
    <div className="App">
      <header className="App-header">
      <div className="title"><h1>EcoCatch</h1></div>
      <div class="wrap">
        <div class="search">
           <input type="text" class="searchTerm" placeholder="Search by waterbody..."/>
           <button type="submit" class="searchButton">
            Submit
          </button>
        </div>
     </div>
      </header>
    </div>
  );
}

export default App;
